class TwoSum
{
    unordered_map< int, int>cnt;
public:
    void add(int number)
    {
        ++cnt[number];
    }
    bool find(int value)
    {
        for (auto&p : cnt)
        {
            long long other = (long long) value - p.first;
            if (other < INT_MIN || other>INT_MAX)
            {
                continue;
            }
            auto it = cnt.find((int) other);
            if (it != cnt.end() && (other != p.first || p.second >= 2))
            {
                return true;
            }
        }
        return false;
    }
};
